create table if not exists public.reporting_schedules (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, scope_type text not null check (scope_type in ('business','fleet','enterprise','admin')), scope_id uuid, name text not null, cadence text not null check (cadence in ('daily','weekly','monthly')), day_of_week smallint, day_of_month smallint, hour_local smallint not null default 8 check (hour_local between 0 and 23), timezone text not null default 'America/Chicago', metrics jsonb not null default '[]'::jsonb, recipients jsonb not null default '[]'::jsonb, enabled boolean not null default true, last_run_at timestamptz, next_run_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists reporting_schedules_owner_idx on public.reporting_schedules(owner_id,enabled);
create index if not exists reporting_schedules_due_idx on public.reporting_schedules(next_run_at) where enabled;
create table if not exists public.reporting_runs (id uuid primary key default gen_random_uuid(), schedule_id uuid not null references public.reporting_schedules(id) on delete cascade, status text not null default 'queued' check(status in ('queued','running','sent','failed')), period_start timestamptz, period_end timestamptz, report_payload jsonb not null default '{}'::jsonb, delivered_to jsonb not null default '[]'::jsonb, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create index if not exists reporting_runs_schedule_idx on public.reporting_runs(schedule_id,created_at desc);
alter table public.reporting_schedules enable row level security;
alter table public.reporting_runs enable row level security;
create policy reporting_schedules_owner_select on public.reporting_schedules for select using (owner_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin or p.is_platform_owner)));
create policy reporting_schedules_owner_insert on public.reporting_schedules for insert with check (owner_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin or p.is_platform_owner)));
create policy reporting_schedules_owner_update on public.reporting_schedules for update using (owner_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin or p.is_platform_owner)));
create policy reporting_schedules_owner_delete on public.reporting_schedules for delete using (owner_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin or p.is_platform_owner)));
create policy reporting_runs_owner_select on public.reporting_runs for select using (exists(select 1 from public.reporting_schedules s where s.id=schedule_id and (s.owner_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and (p.is_admin or p.is_platform_owner)))));
